/* 知夏 · 变量结构
 *
 * 这张卡的玩法是挂机式：妹妹自己在这里活着，玩家离开的那段时间由脚本按**真实时间**折算成她的状态变化。
 * 所以变量分两类：
 * - 会随时间自己变的：妹妹的饥饿、心情、健康，家里的钱
 * - 只由面板动作改的：物品、衣柜
 *
 * 换算规则与上限写在 `脚本/离线结算.ts`，这里只管结构、开局值与合法区间。
 *
 * 前缀约定（MVU 规定）：
 * - 无前缀：AI 可见可更新
 * - `_` 前缀：AI 可见不可更新，只由脚本写
 * - `$` 前缀：AI 看不见，只由脚本写（记账用的都在这里）
 *
 * 数值一律写成 `z.coerce.number().prefault(开局值).transform(钳制)`。
 * 顺序不能反：prefault 是给输入补默认值的，挂在 transform 后面就永远不会生效。
 *
 * 不 import zod 与 lodash：酒馆运行环境自带 `z` 与 `_`。
 */
/** 妹妹从五岁到十六岁，阶段跟着年龄走（1 到 4）。 */
export function 取阶段(年龄) {
    if (年龄 < 7)
        return 1;
    if (年龄 < 9)
        return 2;
    if (年龄 < 12)
        return 3;
    return 4;
}
/** 时段表。只用来显示与让正文对齐，不参与挂机结算。 */
export const 时段表 = ['清晨', '上午', '下午', '傍晚', '夜里', '深夜'];
/** 四个季节。服装按季上架，所以季节是一个真变量。 */
export const 季节表 = ['春', '夏', '秋', '冬'];
const 结构 = z.object({
    时间: z
        .object({
        年: z.coerce.number().prefault(1),
        月: z.coerce
            .number()
            .prefault(9)
            .transform(v => _.clamp(v, 1, 12)),
        日: z.coerce
            .number()
            .prefault(1)
            .transform(v => _.clamp(v, 1, 28)),
        时段: z.string().prefault('傍晚'),
        季节: z.string().prefault('秋'),
        总天数: z.coerce.number().prefault(0),
    })
        .prefault({}),
    钱: z.coerce.number().prefault(320),
    妹妹: z
        .object({
        年龄: z.coerce
            .number()
            .prefault(5)
            .transform(v => _.clamp(v, 5, 16)),
        阶段: z.coerce
            .number()
            .prefault(1)
            .transform(v => _.clamp(v, 1, 4)),
        饥饿: z.coerce
            .number()
            .prefault(70)
            .transform(v => _.clamp(v, 0, 100)),
        心情: z.coerce
            .number()
            .prefault(60)
            .transform(v => _.clamp(v, 0, 100)),
        健康: z.coerce
            .number()
            .prefault(90)
            .transform(v => _.clamp(v, 0, 100)),
        依赖: z.coerce
            .number()
            .prefault(40)
            .transform(v => _.clamp(v, 0, 100)),
        病症: z.string().prefault('无'),
    })
        .prefault({}),
    物品: z
        .record(z.string().describe('物品名'), z.object({
        数量: z.coerce.number().prefault(0),
        类别: z.string().prefault('其他'),
    }))
        .prefault({})
        .transform(表 => _.pickBy(表, 条目 => Number(条目?.数量) > 0)),
    衣柜: z
        .object({
        已购: z.record(z.string().describe('衣服名'), z.coerce.number()).prefault({ 旧T恤: 1, 旧裤子: 1 }),
        当前穿: z.string().prefault('旧T恤'),
    })
        .prefault({}),
    /** 挂机记账：AI 看不到。时间戳是真实毫秒，用来算玩家离开了多久。 */
    $记账: z
        .object({
        上次时刻: z.coerce.number().prefault(0),
        上次结算: z.string().prefault(''),
        已结算次数: z.coerce.number().prefault(0),
    })
        .prefault({}),
});
export const Schema = 结构;
