/* 知夏 · 面板与脚本共用的数据表
 *
 * 只放两样东西：商店的货，和年龄阶段。挂机的换算规则在 `脚本/离线结算.ts`。
 * 面板、脚本、Schema 三处都从这里取，避免各写一份对不上。
 *
 * 不 import 任何东西：酒馆脚本与前端都能直接吃。
 */

export type 商品类别 = '食物' | '药品' | '衣物' | '杂项';

export type 季节 = '春' | '夏' | '秋' | '冬';

/** 一年里的四个季节，顺序固定。 */
export const 季节表: 季节[] = ['春', '夏', '秋', '冬'];

export type 商品 = {
  名: string;
  /** 售价。0 表示开局就有的家底，不上货架。 */
  价: number;
  /** 买回来就吃掉：立刻回的饥饿值。 */
  即食?: number;
  /** 生食材：回家做熟才回饥饿。 */
  熟食回?: number;
  /** 药品治的病症。 */
  治?: '发烧' | '咳嗽' | '肚子疼' | '外伤';
  /** 药品回的健康。 */
  回康?: number;
  /** 心情变化。 */
  心情?: number;
  /** 衣物加的保暖与心情。 */
  保暖?: number;
  心情加成?: number;
  /** 衣物属于哪一档年龄。 */
  档?: '幼' | '学童' | '少年';
  /** 只在哪几个季节上架。不写表示一年四季都有。 */
  季?: 季节[];
  /** 夏装标记：天冷时穿它要挨冻。 */
  露?: boolean;
  /** 一句话，显示在名字下面。 */
  说明: string;
};

