/** 按季节筛货。食品、药品、杂项四季都有；服装看季字段。 */
export function 取当季货架(季节: 季节 | string): 商品[] {
  const 季 = (季节表 as string[]).includes(String(季节)) ? (String(季节) as 季节) : '秋';
  return 商品表.filter(货 => !货.季 || 货.季.includes(季));
}

/** 按类别分组，商店页签直接照这个渲染。 */
export function 取货架分组(季节: 季节 | string): Record<商品类别, 商品[]> {
  const 结果: Record<商品类别, 商品[]> = { 食物: [], 药品: [], 衣物: [], 杂项: [] };
  取当季货架(季节).forEach(货 => {
    const 类别: 商品类别 = 货.治 ? '药品' : 货.档 ? '衣物' : 货.即食 !== undefined || 货.熟食回 !== undefined ? '食物' : '杂项';
    结果[类别].push(货);
  });
  return 结果;
}

/** 一件衣服穿上合不合季。返回一句能直接给玩家看的话。 */
export function 判断穿衣(身上: { 名: string; 保暖: number; 露?: boolean } | null, 季节: 季节 | string) {
  const 季 = (季节表 as string[]).includes(String(季节)) ? (String(季节) as 季节) : '秋';
  if (!身上) return { 状态: '没穿' as const, 说明: '衣柜里没有能穿的。' };
  if (季 === '冬' && 身上.露) return { 状态: '太薄' as const, 说明: `${身上.名}过不了冬，她出门会冻得缩着走。` };
  if (季 === '冬' && 身上.保暖 < 3) return { 状态: '偏薄' as const, 说明: `${身上.名}挡不住这个天气，她回来手脚是凉的。` };
  if (季 === '夏' && 身上.保暖 >= 3) return { 状态: '太厚' as const, 说明: `${身上.名}太闷了，她后背会捂出汗。` };
  return { 状态: '合季' as const, 说明: `${身上.名}这个季节穿正好。` };
}

/* ── 年龄阶段 ────────────────────────────────── */

export type 阶段规格 = { 名: string; 起: number; 止: number; 一句话: string };

export const 阶段表: 阶段规格[] = [
  { 名: '五到六岁', 起: 5, 止: 6, 一句话: '还够不到灶台，什么都得你替她做' },
  { 名: '七到八岁', 起: 7, 止: 8, 一句话: '上学了，开始有自己的事' },
  { 名: '九到十一岁', 起: 9, 止: 11, 一句话: '会顶嘴，也会替你藏着事' },
  { 名: '十二到十六岁', 起: 12, 止: 16, 一句话: '长起来了，开始不想让你看见' },
];

export function 取阶段(年龄: number): 阶段规格 {
  const 钳 = Math.max(5, Math.min(16, Math.floor(年龄)));
  return 阶段表.find(档 => 钳 >= 档.起 && 钳 <= 档.止) ?? 阶段表[0];
}

/** 年龄落在第几阶段（1~4），与变量里的「妹妹.阶段」同义。 */
export function 取阶段号(年龄: number): number {
  const 钳 = Math.max(5, Math.min(16, Math.floor(年龄)));
  if (钳 < 7) return 1;
  if (钳 < 9) return 2;
  if (钳 < 12) return 3;
  return 4;
}
