/* 知夏 · 挂机结算
 *
 * 这张卡的核心：妹妹自己在这里活着。玩家离开多久，她的状态就往下掉多少。
 * 这里用一个**纯函数**算这件事，输入是「上次离开的时刻」和「现在」，输出是一份差额。
 * 纯函数的好处是本地能直接拿数字跑，不必进酒馆；面板与脚本都调同一份，不会各算一套。
 *
 * 三条底线：
 * 1. 离开越久掉得越多，但有上限。上限是「最多按几天算」，超过就按上限算（`最长补偿小时`）。
 * 2. 时间倒退（玩家改了系统时钟）按零处理，不倒涨。
 * 3. 饥饿归零之后健康才开始掉，形成一条连锁，但不至于一夜之间掉光。
 */

/* ── 可调参数：想改松紧就改这里 ───────────────────── */

/** 超过这个时长（小时）就按这个时长算，不再继续掉。72 小时 = 三天。 */
export const 最长补偿小时 = 72;

/** 每过一天妹妹的饥饿掉多少。 */
export const 饥饿日损 = 55;
/** 一次挂机最多掉多少饥饿。这个数要明显高于「一天」的量，否则离开一天和离开一周看起来一样。 */
export const 饥饿上限 = 60;

/** 每过一天心情掉多少。 */
export const 心情日损 = 14;
/** 一次挂机最多掉多少心情。 */
export const 心情上限 = 40;

/** 每过一天健康掉多少（只有在她饿着或者病着的时候才掉）。 */
export const 健康日损 = 8;
/** 一次挂机最多掉多少健康。 */
export const 健康上限 = 12;

/** 她饿到这个数以下，健康才开始跟着掉。 */
export const 饿到这份上会伤身 = 30;

/** 哥哥在外干活的日薪，以及每天的固定开销（房租、水电、米面钱）。 */
export const 日进账 = 180;
export const 日开销 = 120;
/** 一次挂机最多按几天算钱。 */
export const 钱最长结算天数 = 7;

/** 一年按多少天算。用来把「过了几天」折算成年龄。 */
export const 一年天数 = 365;

/* ── 结算本身 ───────────────────────────────── */

export type 差额 = {
  /** 实际按多久算（小时）。被上限截过之后的值。 */
  折合小时: number;
  /** 折算成游戏内天数。 */
  折合天数: number;
  饥饿: number;
  心情: number;
  健康: number;
  钱: number;
  /** 她一个人过了多久，给界面显示与正文引用。 */
  离开小时: number;
  /** 是否被上限截断过。截断时界面要说清楚，免得玩家以为掉这么少是正常的。 */
  被截断: boolean;
};

export type 结算输入 = {
  上次时刻: number;
  现在时刻: number;
  现在的饥饿: number;
  现在的心情: number;
  现在的健康: number;
  现在的钱: number;
  /** 她现在的病症。病着的时候这段时间更伤身。 */
  病症?: string;
};

/** 把毫秒差换成小时，负数与异常值一律按 0。 */
function 小时差(上次时刻: number, 现在时刻: number) {
  const 差 = Number(现在时刻) - Number(上次时刻);
  if (!Number.isFinite(差) || 差 <= 0) return 0;
  return 差 / 3600000;
}

/**
 * 算这一段离开造成的全部变化。
 * 返回的是**差额**（负数代表减少），调用方自己决定怎么加到变量上。
 */
export function 算离线(输入: 结算输入): 差额 {
  const 离开小时 = 小时差(输入.上次时刻, 输入.现在时刻);

  if (离开小时 <= 0) {
    return {
      折合小时: 0,
      折合天数: 0,
      饥饿: 0,
      心情: 0,
      健康: 0,
      钱: 0,
      离开小时: 0,
      被截断: false,
    };
  }

  const 被截断 = 离开小时 > 最长补偿小时;
  const 折合小时 = Math.min(离开小时, 最长补偿小时);
  const 折合天数 = 折合小时 / 24;

  // 饥饿与心情按天数线性掉，各自封顶
  const 饥饿 = -Math.min(饥饿上限, Math.round(折合天数 * 饥饿日损));
  const 心情 = -Math.min(心情上限, Math.round(折合天数 * 心情日损));

  // 健康：只有她本来就饿着、或者正在病着，这段时间才伤身
  let 健康 = 0;
  const 会伤身 = 输入.现在的饥饿 < 饿到这份上会伤身 || (输入.现在的病症 ?? '无') !== '无';
  if (会伤身) 健康 = -Math.min(健康上限, Math.round(折合天数 * 健康日损));

  // 钱：这几天他也在外面干活，扣掉固定开销
  const 钱天数 = Math.min(折合天数, 钱最长结算天数);
  const 净额 = 日进账 - 日开销;
  const 钱 = Math.round(钱天数 * 净额);

  return { 折合小时, 折合天数, 饥饿, 心情, 健康, 钱, 离开小时, 被截断 };
}

/** 把小时数说成人话，界面与正文都用这一句。 */
export function 说时长(小时: number) {
  if (小时 < 1) return '不到一个小时';
  if (小时 < 24) return `${Math.round(小时)} 个小时`;
  const 天 = Math.floor(小时 / 24);
  const 余 = Math.round(小时 - 天 * 24);
  return 余 > 0 ? `${天} 天 ${余} 小时` : `${天} 天`;
}

export type 收支 = {
  /** 这一趟是不是刚好跨过了生日，界面要单独提一句。 */
  年龄长了一岁: boolean;
};

/** 把差额应用到一份变量上。就地改，调用方传进来的那份。 */
export function 应用到妹妹(数据: any, 差额: 差额): 收支 {
  const 钳 = (值: number) => Math.max(0, Math.min(100, 值));
  数据.妹妹.饥饿 = 钳(Number(数据.妹妹.饥饿) + 差额.饥饿);
  数据.妹妹.心情 = 钳(Number(数据.妹妹.心情) + 差额.心情);
  数据.妹妹.健康 = 钳(Number(数据.妹妹.健康) + 差额.健康);
  数据.钱 = Math.max(0, Number(数据.钱) + 差额.钱);
  数据.时间.总天数 = Number(数据.时间.总天数 ?? 0) + Math.round(差额.折合天数);

  // 天数推着年龄走：每满一年长一岁，阶段跟着改
  const 原年龄 = Number(数据.妹妹.年龄);
  const 新年龄 = Math.min(16, 5 + Math.floor(Number(数据.时间.总天数 ?? 0) / 一年天数));
  let 年龄长了一岁 = false;
  if (新年龄 !== 原年龄) {
    数据.妹妹.年龄 = 新年龄;
    数据.妹妹.阶段 = 取阶段(新年龄);
    年龄长了一岁 = 新年龄 > 原年龄;
  }
  return { 年龄长了一岁 };
}

function 取阶段(年龄: number) {
  if (年龄 < 7) return 1;
  if (年龄 < 9) return 2;
  if (年龄 < 12) return 3;
  return 4;
}
